recipes.code:
{
  "inputs": [
    {
      "id": "ausdata-api-key",
      "type": "promptString",
      "description": "ausdata.io API key (free tier at https://ausdata.io)",
      "password": true
    }
  ],
  "servers": {
    "ausdata": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "ausdata-mcp@0.4.2"
      ],
      "env": {
        "AUSDATA_API_KEY": "${input:ausdata-api-key}"
      }
    }
  }
}
